Write a Python function `parse_env_file(text: str) -> dict[str, str]` that parses `.env`-style configuration text. Ignore blank lines and lines starting with `#` (after stripping leading whitespace). Split each key-value line on the first `=`. Strip surrounding whitespace from keys and values, and if a value is enclosed in matching single or double quotes, remove the outer quotes. Return a dictionary mapping keys to values.

Example assertions:
assert parse_env_file('HOST=localhost\nPORT="8080"') == {'HOST': 'localhost', 'PORT': '8080'}
assert parse_env_file('# comment\nKEY=a=b=c') == {'KEY': 'a=b=c'}

reference:
def parse_env_file(text: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#') or '=' not in line:
            continue
        k, v = line.split('=', 1)
        k, v = k.strip(), v.strip()
        if len(v) >= 2 and v[0] == v[-1] and v[0] in ('"', "'"):
            v = v[1:-1]
        out[k] = v
    return out

def compare_semver(v1: str, v2: str) -> int:
    def norm(v: str) -> tuple[int, int, int]:
        parts = [int(p) for p in v.strip().lstrip('vV').split('.')]
        while len(parts) < 3:
            parts.append(0)
        return (parts[0], parts[1], parts[2])
    a, b = norm(v1), norm(v2)
    return -1 if a < b else (1 if a > b else 0)

def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []
    s = sorted(intervals)
    merged = [s[0]]
    for a, b in s[1:]:
        pa, pb = merged[-1]
        if a <= pb:
            merged[-1] = (pa, max(pb, b))
        else:
            merged.append((a, b))
    return merged

from collections import OrderedDict
def simulate_lru(capacity: int, ops: list[tuple]) -> list[int]:
    cache: OrderedDict[int, int] = OrderedDict()
    out: list[int] = []
    for op in ops:
        if op[0] == 'get':
            k = op[1]
            if k in cache:
                cache.move_to_end(k)
                out.append(cache[k])
            else:
                out.append(-1)
        else:
            _, k, v = op
            cache[k] = v
            cache.move_to_end(k)
            if len(cache) > capacity:
                cache.popitem(last=False)
    return out

def is_balanced_brackets(s: str) -> bool:
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack: list[str] = []
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

