Write a Python function `flatten_json(obj: dict, sep: str = '.') -> dict` that recursively flattens nested dictionaries into a single-level dictionary whose keys are joined by `sep`. Non-dict values (including lists, ints, strings, None, empty dicts `{}`) are kept as leaf values.

Example assertions:
assert flatten_json({'a': {'b': 1, 'c': {'d': 2}}}) == {'a.b': 1, 'a.c.d': 2}
assert flatten_json({'x': [1, 2], 'y': {}}) == {'x': [1, 2], 'y': {}}

reference:
def flatten_json(obj: dict, sep: str = '.') -> dict:
    out = {}
    def walk(d: dict, prefix: str) -> None:
        for k, v in d.items():
            nk = f'{prefix}{sep}{k}' if prefix else str(k)
            if isinstance(v, dict) and v:
                walk(v, nk)
            else:
                out[nk] = v
    walk(obj, '')
    return out

