import re
def summarize_logs(lines: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    pat = re.compile(r'^\s*\[([A-Z]+)\]\s+')
    for ln in lines:
        m = pat.match(ln)
        if m:
            lvl = m.group(1)
            counts[lvl] = counts.get(lvl, 0) + 1
    return counts

def rle_encode(s: str) -> str:
    if not s:
        return ''
    out = []
    cur, cnt = s[0], 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            out.append(f'{cur}{cnt}')
            cur, cnt = ch, 1
    out.append(f'{cur}{cnt}')
    return ''.join(out)

def normalize_unix_path(path: str) -> str:
    stack: list[str] = []
    for part in path.split('/'):
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

import heapq
def topo_sort_tasks(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps.keys())
    for pres in deps.values():
        nodes.update(pres)
    indeg = {n: 0 for n in nodes}
    adj: dict[str, list[str]] = {n: [] for n in nodes}
    for task, pres in deps.items():
        for p in pres:
            adj[p].append(task)
            indeg[task] += 1
    heap = [n for n, d in indeg.items() if d == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    return order if len(order) == len(nodes) else []

from collections import deque
def allow_requests(timestamps: list[int], window: int, limit: int) -> list[bool]:
    q: deque[int] = deque()
    res: list[bool] = []
    for t in timestamps:
        while q and q[0] <= t - window:
            q.popleft()
        if len(q) < limit:
            q.append(t)
            res.append(True)
        else:
            res.append(False)
    return res

