Write a Python function `parse_cli_flags(tokens: list[str]) -> dict[str, str | bool]` that parses CLI argument tokens. Flags start with `--`. If `--flag=value` is given, store `flag: value`. If `--flag` is followed by a non-flag token (not starting with `--`), store `flag: next_token`. Otherwise store `flag: True`. Ignore standalone positional tokens.

Example assertions:
assert parse_cli_flags(['--host', '0.0.0.0', '--verbose', '--port=8080']) == {'host': '0.0.0.0', 'verbose': True, 'port': '8080'}
assert parse_cli_flags(['--dry-run']) == {'dry-run': True}

reference:
def parse_cli_flags(tokens: list[str]) -> dict[str, str | bool]:
    out: dict[str, str | bool] = {}
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok.startswith('--') and len(tok) > 2:
            body = tok[2:]
            if '=' in body:
                k, v = body.split('=', 1)
                out[k] = v
                i += 1
            elif i + 1 < len(tokens) and not tokens[i + 1].startswith('--'):
                out[body] = tokens[i + 1]
                i += 2
            else:
                out[body] = True
                i += 1
        else:
            i += 1
    return out

import re
def extract_markdown_links(md: str) -> list[tuple[str, str]]:
    return re.findall(r'(?<!!)\[([^\]]+)\]\(([^)]+)\)', md)

def dedupe_preserve_order(items: list[dict], key: str) -> list[dict]:
    seen = set()
    out = []
    for item in items:
        if key not in item:
            continue
        val = item[key]
        if val not in seen:
            seen.add(val)
            out.append(item)
    return out
